{
  "status": "SUPPORTED",
  "task_summary": "Find fastening hardware and tool, fasten the target on the table, then place the tool on the table.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "fastening_target",
        "entity_kind": "FIXED_TARGET",
        "function": "The specific location or object on the workbench that needs to be secured.",
        "required_count": 1,
        "binding_policy": "SHARED"
      ,
        "candidate_categories": ["assembly_point", "target_object"],
        "required_properties": ["needs_fastening"]
      },
      {
        "id": "fastening_component",
        "entity_kind": "OBJECT",
        "function": "The hardware (screw, bolt, etc.) used to secure the target.",
        "required_count": 1,
        "binding_policy": "DISTINCT"
      ,
        "candidate_categories": ["screw", "bolt", "nut", "washer"],
        "required_properties": ["compatible_with_target", "usable_for_fastening"]
      },
      {
        "id": "fastening_tool",
        "entity_kind": "OBJECT",
        "function": "The implement used to apply the fastening force.",
        "required_count": 1,
        "binding_policy": "REUSABLE"
      ,
        "candidate_categories": ["screwdriver", "wrench", "pliers"],
        "required_properties": ["usable_for_fastening"]
      },
      {
        "id": "workbench",
        "entity_kind": "REGION",
        "function": "The surface where the task takes place and where the tool is left.",
        "required_count": 1,
        "binding_policy": "SHARED"
      ,
        "candidate_categories": ["table", "surface"],
        "required_properties": ["flat_surface"]
      }
    ],
    "functional_relations": [
      {
        "id": "compatible_with",
        "relation": "Fastening Component is compatible with Fastening Target.",
        "participant_roles": [
          "fastening_component",
          "fastening_target"
        ]
      ,
        "required": true
      },
      {
        "id": "operates_on",
        "relation": "Fastening Tool operates on Fastening Component and Fastening Target.",
        "participant_roles": [
          "fastening_tool",
          "fastening_component",
          "fastening_target"
        ]
      ,
        "required": true
      },
      {
        "id": "placed_on",
        "relation": "Fastening Tool ends up on Workbench.",
        "participant_roles": [
          "fastening_tool",
          "workbench"
        ]
      ,
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "retrieve_fastening_component",
        "operation": "Retrieve Fastening Component",
        "participant_roles": [
          "fastening_component"
        ,
          "fastening_tool"
        ],
        "operation_count": 1
      },
      {
        "id": "fasten",
        "operation": "Fasten",
        "participant_roles": [
          "fastening_tool",
          "fastening_component",
          "fastening_target"
        ],
        "operation_count": 1
      },
      {
        "id": "place_fastening_tool",
        "operation": "Place Fastening Tool",
        "participant_roles": [
          "fastening_tool",
          "workbench"
        ],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "fastening_target": [
        {
          "label": "Black tray with yellow/blue object on table",
          "visual_description": "A black rectangular tray holding a yellow object with a blue end, sitting on the wooden table."
        }
      ],
      "workbench": [
        {
          "label": "Wooden table",
          "visual_description": "A wooden desk with two drawers underneath."
        }
      ],
      "fastening_component": [],
      "fastening_tool": []
    },
    "inspectable_regions": [
      {
        "id": "left_drawer",
        "label": "Left Drawer",
        "visual_description": "Closed blue drawer under the left side of the table.",
        "reason": "Likely contains small hardware or tools."
      },
      {
        "id": "right_drawer",
        "label": "Right Drawer",
        "visual_description": "Closed blue drawer under the right side of the table.",
        "reason": "Likely contains small hardware or tools."
      },
      {
        "id": "cabinet",
        "label": "Cabinet",
        "visual_description": "Closed tall blue cabinet against the back wall.",
        "reason": "Likely contains larger tools or components."
      }
    ],
    "inspection_order": [
      "left_drawer",
      "right_drawer",
      "cabinet"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
